NativeSignal grp1_apply_text_alias_table(VM& vm, Thread& thread) {
    const uint32_t source = thread.stack.pop();
    if (source == 0) {
        thread.stack.push(0);
        return NativeSignal::Continue;
    }

    const std::string text =
        vm.memory().read_cstring(source, thread.base);
    std::size_t cursor = 0;
    while (cursor < text.size()) {
        const std::size_t separator = text.find('\\', cursor);
        if (separator == std::string::npos) {
            break;
        }
        if (separator == cursor) {
            cursor = separator + 1U;
            continue;
        }
        const std::string key = normalize_text_to_utf8(
            std::string_view(text).substr(cursor, separator - cursor));
        const std::size_t value_start = separator + 1U;
        const std::size_t newline = text.find('\n', value_start);
        const std::size_t value_end =
            newline == std::string::npos ? text.size() : newline;
        if (value_end == value_start) {
            cursor = newline == std::string::npos ? text.size()
                                                 : newline + 1U;
            continue;
        }
        const std::string value = normalize_text_to_utf8(
            std::string_view(text).substr(
                value_start, value_end - value_start));
        vm.set_rich_text_alias(key, value);
        cursor = newline == std::string::npos ? text.size()
                                              : newline + 1U;
    }
    thread.stack.push(1);
    return NativeSignal::Continue;
}
